import Foundation
import Network

/// A deterministic, loopback-only Xtream-shaped provider used for the clearly labeled
/// sample experience and for end-to-end tests.
///
/// - Binds to 127.0.0.1 only; nothing is reachable from the network.
/// - Serves only synthetic JSON and media generated by `scripts/generate-fixture-media.sh`
///   from ffmpeg test-pattern generators (no third-party content, logos or artwork).
/// - Exercises the real code path: URLSession metadata requests, credential-bearing stream
///   URLs (the fixture password deliberately contains reserved URL characters) and AVPlayer
///   over HTTP, including a live sliding-window HLS playlist and failure scenarios.
public final class FixtureServer: @unchecked Sendable {
    /// Fixture-only values. They grant access to nothing except this local server.
    public static let username = "seyrileo-demo"
    public static let password = "fixture pass/#?&+%"
    public static let expiredUsername = "seyrileo-expired"
    public static let defaultPort: UInt16 = 47_816

    public enum Channel: String, CaseIterable, Sendable {
        case patternA = "101"
        case patternB = "102"
        case mpegTSOnly = "201"
        case offline = "202"
        case forbidden = "203"
        case corrupt = "204"
        case mp2Audio = "205"
    }

    public enum ServerError: Error, Equatable {
        case mediaMissing
        case listenerFailed(String)
    }

    private let requestedPort: UInt16
    private let now: @Sendable () -> Date
    private let queue = DispatchQueue(label: "fixture-server")
    private let lock = NSLock()
    private var listener: NWListener?
    private var boundPort: UInt16?
    private let media: FixtureMedia

    public init(port: UInt16 = 0, now: @escaping @Sendable () -> Date = Date.init) throws {
        guard let media = FixtureMedia(bundle: .module) else { throw ServerError.mediaMissing }
        self.requestedPort = port
        self.now = now
        self.media = media
    }

    deinit { listener?.cancel() }

    /// `http://localhost:<port>` once started.
    public var baseURL: URL? {
        lock.withLock { boundPort }.map { URL(string: "http://localhost:\($0)")! }
    }

    public var isRunning: Bool {
        lock.withLock { listener?.state == .ready }
    }

    /// Starts (or keeps) the listener and returns the bound port.
    @discardableResult
    public func start() async throws -> UInt16 {
        if let port = lock.withLock({ listener?.state == .ready ? boundPort : nil }) { return port }
        stop()

        let parameters = NWParameters.tcp
        parameters.allowLocalEndpointReuse = true
        let port: NWEndpoint.Port = requestedPort == 0 ? .any : NWEndpoint.Port(rawValue: requestedPort)!
        parameters.requiredLocalEndpoint = .hostPort(host: .ipv4(.loopback), port: port)
        let listener: NWListener
        do {
            listener = try NWListener(using: parameters)
        } catch {
            throw ServerError.listenerFailed(String(describing: error))
        }
        listener.newConnectionHandler = { [weak self] connection in
            self?.accept(connection)
        }
        lock.withLock { self.listener = listener }

        return try await withCheckedThrowingContinuation { continuation in
            let resumed = LockedFlag()
            listener.stateUpdateHandler = { [weak self, weak listener] state in
                switch state {
                case .ready:
                    let port = listener?.port?.rawValue ?? 0
                    self?.lock.withLock { self?.boundPort = port }
                    if resumed.set() { continuation.resume(returning: port) }
                case .failed(let error):
                    listener?.cancel()
                    if resumed.set() { continuation.resume(throwing: ServerError.listenerFailed(String(describing: error))) }
                case .cancelled:
                    if resumed.set() { continuation.resume(throwing: ServerError.listenerFailed("cancelled")) }
                default:
                    break
                }
            }
            listener.start(queue: queue)
        }
    }

    public func stop() {
        let listener = lock.withLock { () -> NWListener? in
            let current = self.listener
            self.listener = nil
            self.boundPort = nil
            return current
        }
        listener?.cancel()
    }

    // MARK: - Connections

    private func accept(_ connection: NWConnection) {
        connection.start(queue: queue)
        receive(on: connection, buffer: Data())
    }

    private func receive(on connection: NWConnection, buffer: Data) {
        connection.receive(minimumIncompleteLength: 1, maximumLength: 16 * 1024) { [weak self] data, _, isComplete, error in
            guard let self, error == nil else { connection.cancel(); return }
            var buffer = buffer
            if let data { buffer.append(data) }
            if let headerEnd = buffer.range(of: Data("\r\n\r\n".utf8)) {
                let head = String(decoding: buffer[..<headerEnd.lowerBound], as: UTF8.self)
                self.respond(to: head, on: connection)
            } else if isComplete || buffer.count > 16 * 1024 {
                connection.cancel()
            } else {
                self.receive(on: connection, buffer: buffer)
            }
        }
    }

    private func respond(to head: String, on connection: NWConnection) {
        let requestLine = head.split(separator: "\r\n", maxSplits: 1).first.map(String.init) ?? ""
        let parts = requestLine.split(separator: " ")
        let response: FixtureResponse
        if parts.count >= 2, parts[0] == "GET" || parts[0] == "HEAD" {
            response = route(target: String(parts[1]))
        } else {
            response = .text(405, "method not allowed")
        }
        let isHead = parts.first == "HEAD"
        let headers = Self.parseHeaders(head)
        var status = response.status
        var body = response.body
        var extraHeaders = ""
        // Single byte-range support, as AVFoundation expects for progressive media.
        if !response.isUnboundedStream, status == 200,
           let range = headers["range"].flatMap({ Self.parseRange($0, length: body.count) }) {
            status = 206
            extraHeaders = "Content-Range: bytes \(range.lowerBound)-\(range.upperBound)/\(body.count)\r\n"
            body = body.subdata(in: range.lowerBound..<(range.upperBound + 1))
        }
        var header = "HTTP/1.1 \(status) \(FixtureResponse.reason(status))\r\n"
        header += "Content-Type: \(response.contentType)\r\n"
        if response.isUnboundedStream {
            // Like an Xtream ".ts" live output: no length, no ranges, body ends when the
            // connection closes.
            extraHeaders += "Accept-Ranges: none\r\n"
        } else {
            header += "Content-Length: \(body.count)\r\n"
            header += "Accept-Ranges: bytes\r\n"
        }
        header += extraHeaders
        header += "Cache-Control: no-store\r\n"
        header += "Connection: close\r\n\r\n"
        var payload = Data(header.utf8)
        if !isHead { payload.append(body) }
        connection.send(content: payload, completion: .contentProcessed { _ in connection.cancel() })
    }

    // MARK: - Routing

    func route(target: String) -> FixtureResponse {
        let pathPart = target.split(separator: "?", maxSplits: 1, omittingEmptySubsequences: false).first.map(String.init) ?? ""
        let query = target.contains("?") ? String(target[target.index(after: target.firstIndex(of: "?")!)...]) : ""
        // Split on the raw "/" first, then decode each segment, so an encoded "/" inside a
        // credential stays part of that credential.
        let segments = pathPart.split(separator: "/").map { String($0).removingPercentEncoding ?? String($0) }

        if segments == ["player_api.php"] {
            return playerAPI(query: Self.parseQuery(query))
        }
        if segments.count == 4, segments[0] == "live" {
            return liveStream(username: segments[1], password: segments[2], file: segments[3])
        }
        if segments.count == 4, segments[0] == "movie" || segments[0] == "series" {
            return onDemandStream(kind: segments[0], username: segments[1], password: segments[2], file: segments[3])
        }
        if segments.count == 3, segments[0] == "fixture-media" {
            return mediaFile(directory: segments[1], file: segments[2])
        }
        return .text(404, "not found")
    }

    static func parseHeaders(_ head: String) -> [String: String] {
        var headers: [String: String] = [:]
        for line in head.split(separator: "\r\n").dropFirst() {
            guard let colon = line.firstIndex(of: ":") else { continue }
            headers[line[..<colon].lowercased()] = line[line.index(after: colon)...].trimmingCharacters(in: .whitespaces)
        }
        return headers
    }

    /// Parses "bytes=a-b", "bytes=a-" and "bytes=-n" into a closed range.
    static func parseRange(_ value: String, length: Int) -> ClosedRange<Int>? {
        guard length > 0, value.hasPrefix("bytes="), !value.contains(",") else { return nil }
        let spec = value.dropFirst(6).split(separator: "-", maxSplits: 1, omittingEmptySubsequences: false)
        guard spec.count == 2 else { return nil }
        let start: Int, end: Int
        if spec[0].isEmpty {
            guard let suffix = Int(spec[1]), suffix > 0 else { return nil }
            start = max(0, length - suffix)
            end = length - 1
        } else {
            guard let first = Int(spec[0]), first < length else { return nil }
            start = first
            end = spec[1].isEmpty ? length - 1 : min(Int(spec[1]) ?? length - 1, length - 1)
        }
        return start <= end ? start...end : nil
    }

    static func parseQuery(_ query: String) -> [String: String] {
        var result: [String: String] = [:]
        for pair in query.split(separator: "&") {
            let kv = pair.split(separator: "=", maxSplits: 1, omittingEmptySubsequences: false)
            // PHP semantics: "+" means space in query strings.
            func decode(_ s: Substring) -> String {
                String(s).replacingOccurrences(of: "+", with: " ").removingPercentEncoding ?? String(s)
            }
            if let key = kv.first { result[decode(key)] = kv.count > 1 ? decode(kv[1]) : "" }
        }
        return result
    }

    private func status(for username: String, password: String) -> String? {
        guard password == Self.password else { return nil }
        switch username {
        case Self.username: return "Active"
        case Self.expiredUsername: return "Expired"
        default: return nil
        }
    }

    private func playerAPI(query: [String: String]) -> FixtureResponse {
        guard let status = status(for: query["username"] ?? "", password: query["password"] ?? "") else {
            return .json(#"{"user_info":{"auth":0}}"#)
        }
        switch query["action"] {
        case nil:
            return .json(FixtureCatalog.authJSON(username: query["username"] ?? "", status: status, port: lock.withLock { boundPort } ?? 0))
        case "get_live_categories":
            return .json(FixtureCatalog.liveCategoriesJSON)
        case "get_live_streams":
            return .json(FixtureCatalog.liveStreamsJSON(categoryID: query["category_id"]))
        case "get_vod_categories":
            return .json(FixtureCatalog.vodCategoriesJSON)
        case "get_vod_streams":
            return .json(FixtureCatalog.vodStreamsJSON)
        case "get_vod_info":
            return .json(FixtureCatalog.vodInfoJSON(id: query["vod_id"] ?? ""))
        case "get_series_categories":
            return .json(FixtureCatalog.seriesCategoriesJSON)
        case "get_series":
            return .json(FixtureCatalog.seriesJSON)
        case "get_series_info":
            return .json(FixtureCatalog.seriesInfoJSON(id: query["series_id"] ?? ""))
        default:
            // Other actions are not part of the Milestone 1 fixture; an empty list is what
            // many real panels return for unknown or empty actions.
            return .json("[]")
        }
    }

    private func liveStream(username: String, password: String, file: String) -> FixtureResponse {
        guard status(for: username, password: password) == "Active" else { return .text(403, "forbidden") }
        let id = file.split(separator: ".").first.map(String.init) ?? ""
        let ext = file.split(separator: ".").dropFirst().first.map(String.init) ?? ""
        guard let channel = Channel(rawValue: id) else { return .text(404, "unknown stream") }
        switch channel {
        case .patternA, .patternB, .mp2Audio:
            let directory = channel == .patternA ? "pattern-a" : channel == .patternB ? "pattern-b" : "pattern-mp2"
            if ext == "ts" { return .data(200, "video/mp2t", media.rawTS) }
            guard let playlist = media.livePlaylist(directory: directory, now: now()) else { return .text(500, "media") }
            return .data(200, "application/vnd.apple.mpegurl", Data(playlist.utf8))
        case .mpegTSOnly:
            // Simulates a provider that only delivers a live raw MPEG-TS stream regardless of
            // extension: no Content-Length and no byte ranges (a few loops, then close).
            var body = Data()
            for _ in 0..<3 { body.append(media.rawTS) }
            return FixtureResponse(status: 200, contentType: "video/mp2t", body: body, isUnboundedStream: true)
        case .offline:
            return .text(404, "stream offline")
        case .forbidden:
            return .text(403, "forbidden")
        case .corrupt:
            let playlist = """
                #EXTM3U
                #EXT-X-VERSION:3
                #EXT-X-TARGETDURATION:2
                #EXT-X-MEDIA-SEQUENCE:0
                #EXTINF:2.0,
                /fixture-media/corrupt/seg0.ts
                #EXTINF:2.0,
                /fixture-media/corrupt/seg1.ts
                #EXT-X-ENDLIST

                """
            return .data(200, "application/vnd.apple.mpegurl", Data(playlist.utf8))
        }
    }

    /// Progressive files with byte ranges (as real Xtream VOD outputs are served).
    private func onDemandStream(kind: String, username: String, password: String, file: String) -> FixtureResponse {
        guard status(for: username, password: password) == "Active" else { return .text(403, "forbidden") }
        switch (kind, file) {
        case ("movie", "301.mp4"), ("series", "501.mp4"), ("series", "502.mp4"), ("series", "503.mp4"):
            return .data(200, "video/mp4", media.featureMP4)
        case ("movie", "302.mkv"):
            return .data(200, "video/x-matroska", media.shortMKV)
        default:
            return .text(404, "not found")
        }
    }

    private func mediaFile(directory: String, file: String) -> FixtureResponse {
        if directory == "corrupt" { return .data(200, "video/mp2t", FixtureMedia.corruptSegment) }
        guard let data = media.segment(directory: directory, file: file) else { return .text(404, "not found") }
        return .data(200, "video/mp2t", data)
    }
}

struct FixtureResponse {
    let status: Int
    let contentType: String
    let body: Data
    var isUnboundedStream = false

    static func json(_ text: String) -> FixtureResponse {
        FixtureResponse(status: 200, contentType: "application/json; charset=utf-8", body: Data(text.utf8))
    }

    static func text(_ status: Int, _ text: String) -> FixtureResponse {
        FixtureResponse(status: status, contentType: "text/plain; charset=utf-8", body: Data(text.utf8))
    }

    static func data(_ status: Int, _ contentType: String, _ body: Data) -> FixtureResponse {
        FixtureResponse(status: status, contentType: contentType, body: body)
    }

    static func reason(_ status: Int) -> String {
        switch status {
        case 200: "OK"
        case 206: "Partial Content"
        case 403: "Forbidden"
        case 404: "Not Found"
        case 405: "Method Not Allowed"
        default: "Error"
        }
    }
}

private final class LockedFlag: @unchecked Sendable {
    private let lock = NSLock()
    private var value = false

    /// Returns true only the first time.
    func set() -> Bool {
        lock.withLock {
            defer { value = true }
            return !value
        }
    }
}
